369	        .arg(&missing)
370	        .output()
371	        .expect("running chainview");
372	    assert_eq!(out.status.code(), Some(2));
373	    assert!(out.stdout.is_empty());
374	    let stderr = lossy(&out.stderr);
375	    assert!(
376	        stderr.starts_with(&format!(
377	            "chainview: cannot read certificate file '{}': ",
378	            missing.display()
379	        )),
380	        "unexpected stderr: {stderr}"
381	    );
382	}
383	
384	// ----- Assertions / process plumbing --------------------------------------
385	
386	fn assert_success(out: &Output, subject: &str, issuer: &str) {
387	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
388	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
389	    assert_eq!(
390	        lossy(&out.stdout),
391	        format!(
392	            "Subject: {subject}\n\
393	             Issuer: {issuer}\n\
394	             Serial Number: {FIXED_SERIAL}\n\
395	             Not Before: {FIXED_NOT_BEFORE}\n\
396	             Not After: {FIXED_NOT_AFTER}\n"
397	        )
398	    );
399	}
400	
401	/// Every malformed-input case shares the documented contract: exit code 2,
402	/// nothing on stdout (so no name field can be printed before the error is
403	/// noticed), and the fixed invalid-certificate message prefix on stderr.
404	fn assert_invalid_certificate(out: &Output) {
405	    assert_eq!(
406	        out.status.code(),
407	        Some(2),
408	        "stdout={} stderr={}",
409	        lossy(&out.stdout),
410	        lossy(&out.stderr)
411	    );
412	    assert!(
413	        out.stdout.is_empty(),
414	        "stdout must be empty on failure, got: {}",
415	        lossy(&out.stdout)
416	    );
417	    let stderr = lossy(&out.stderr);
418	    assert!(
419	        stderr.starts_with("chainview: invalid DER certificate: "),
420	        "unexpected stderr: {stderr}"
421	    );
422	    // A non-empty reason after the fixed prefix.
423	    assert!(
424	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
425	        "missing error reason in stderr: {stderr}"
426	    );
427	}
428	
429	fn lossy(bytes: &[u8]) -> String {
430	    String::from_utf8_lossy(bytes).into_owned()
431	}
432	
433	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
434	    let cert = TempCert::new(tag, data);
435	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
436	        .arg("inspect")
437	        .arg(&cert.path)
438	        .output()
439	        .expect("running chainview");
440	    (output, cert)
441	}
442	
443	struct TempCert {
444	    path: PathBuf,
445	}
446	
447	impl TempCert {
448	    fn new(tag: &str, data: &[u8]) -> Self {
449	        static COUNTER: AtomicU64 = AtomicU64::new(0);
450	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
451	        let path = std::env::temp_dir().join(format!(
452	            "chainview-name-test-{}-{tag}-{unique}.der",
453	            std::process::id()
454	        ));
455	        fs::write(&path, data).expect("writing temp certificate");
456	        TempCert { path }
457	    }
458	}
459	
460	impl Drop for TempCert {
461	    fn drop(&mut self) {
462	        let _ = fs::remove_file(&self.path);
463	    }
464	}
465	
466	// ----- Certificate / DER construction -------------------------------------
467	//
468	// Only the structural pieces needed here. Lengths are always emitted in the
469	// minimal DER form, except where a test injects raw bytes to exercise
470	// rejection of non-minimal or truncated encodings.
471	
472	fn simple_cn_name(cn: &str) -> Vec<u8> {
473	    name(&[rdn(&[atv_utf8(CN, cn)])])
474	}
475	
476	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
477	/// validity and key material around the supplied Subject/Issuer names.
478	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
479	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
480	    let validity = seq(&concat(&[
481	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
482	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
483	    ]));
484	    let spki = seq(&concat(&[
485	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
486	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
487	    ]));
488	
489	    let tbs = seq(&concat(&[
490	        &serial,
491	        &signature_algorithm(),
492	        issuer,
493	        &validity,
494	        subject,
495	        &spki,
496	    ]));
497	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
498	}
499	
500	fn signature_algorithm() -> Vec<u8> {
501	    // sha256WithRSAEncryption with explicit NULL parameters.
502	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
503	}
504	
505	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
506	    tlv(
507	        0x30,
508	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
509	    )
510	}
511	
512	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
513	    tlv(
514	        0x31,
515	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
516	    )
517	}
518	
519	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
520	/// complete DER TLV of the value.
521	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
522	    seq(&concat(&[&oid(arcs), value]))
523	}
524	
525	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
526	    atv(arcs, &tlv(0x0C, text.as_bytes()))
527	}
528	
529	fn oid(arcs: &[u64]) -> Vec<u8> {
530	    assert!(arcs.len() >= 2);
531	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
532	    for &arc in &arcs[2..] {
533	        content.extend_from_slice(&oid_arc(arc));
534	    }
535	    tlv(0x06, &content)
536	}
537	
538	fn oid_arc(mut value: u64) -> Vec<u8> {
539	    let mut out = vec![(value % 128) as u8];
540	    value /= 128;
541	    while value > 0 {
542	        out.push(0x80 | (value % 128) as u8);
543	        value /= 128;
544	    }
545	    out.reverse();
546	    out
547	}
548	
549	fn seq(content: &[u8]) -> Vec<u8> {
550	    tlv(0x30, content)
551	}
552	
553	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
554	    let mut out = vec![tag];
555	    out.extend_from_slice(&der_len(content.len()));
556	    out.extend_from_slice(content);
557	    out
558	}
559	
560	fn der_len(n: usize) -> Vec<u8> {
561	    if n < 0x80 {
562	        vec![n as u8]
563	    } else {
564	        let mut body = Vec::new();
565	        let mut v = n;
566	        while v > 0 {
567	            body.push((v & 0xFF) as u8);
568	            v >>= 8;
569	        }
570	        body.reverse();
571	        let mut out = vec![0x80 | body.len() as u8];
572	        out.extend_from_slice(&body);
573	        out
574	    }
575	}
576	
577	fn concat(parts: &[&[u8]]) -> Vec<u8> {
578	    let mut out = Vec::new();
579	    for part in parts {
580	        out.extend_from_slice(part);
581	    }
582	    out
583	}
584	
585	fn hex(bytes: &[u8]) -> String {
586	    let mut s = String::with_capacity(bytes.len() * 2);
587	    for b in bytes {
588	        use std::fmt::Write;
589	        write!(s, "{b:02X}").unwrap();
590	    }
591	    s
592	}
593

