    // the CN TLV sorts after the 1.2.3.4 TLV, so this SET OF violates DER
    // ordering even though every attribute is individually well-formed.
    let subject = name(&[rdn(&[atv_utf8(CN, "a"), atv_utf8(&[1, 2, 3, 4], "z")])]);
